"""Build the Six Seven score from its curated song asset, without accessing a device."""

import json
import pathlib

ROOT = pathlib.Path(__file__).resolve().parents[1]


def build():
    score = json.loads((ROOT / "assets" / "six_seven.json").read_text(encoding="ascii"))
    lines = [
        "// Generated by tools/build_six_seven.py from assets/six_seven.json.",
        "#pragma once",
        '#include "engine.h"',
        "namespace orbit {",
        "inline constexpr Session SixSevenSong = [] {",
        "    Session song;",
    ]

    def boolean(value):
        return "true" if value else "false"

    def section(data, target):
        for index, track in enumerate(data["tracks"]):
            notes = track["notes"]
            lines.append(f"    {target}.tracks[{index}] = Track{{"
                         f'{len(notes)}, {track["patch"]}, {track["tone"]}, {track["space"]}, '
                         f'{boolean(track["muted"])}, {{')
            for tick, duration, pad, velocity in notes:
                lines.append(f"        {{{tick}, {duration}, {pad}, {velocity}}},")
            lines.append(f'    }}, {track["pitch"]}, 0}};')
        lines.append(f'    {target}.slices = {boolean(data["slices"])};')
        lines.append(f'    {target}.fx.enabled = {boolean(data["fx"]["enabled"])};')
        for index, x, y, active in data["fx"]["points"]:
            lines.append(f"    {target}.fx.points[{index}] = FxPoint{{{x}, {y}, {boolean(active)}}};")

    for key in ("bpm", "root", "scale", "swing"):
        lines.append(f'    song.{key} = {score[key]};')
    lines.append(f'    song.activeScene = {score["active_scene"]};')
    section(score, "song")
    for index, scene in enumerate(score["scenes"]):
        section(scene, f"song.scenes[{index}]")
    lines.extend(["    return song;", "}();", "}", ""])
    (ROOT / "Orbit" / "six_seven.h").write_text("\n".join(lines), encoding="ascii")


if __name__ == "__main__":
    build()
